/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import readline from 'readline'

const mode = process.argv[2]

// Validate mode argument
if (!mode || !['rounds', 'tally'].includes(mode)) {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}

// Read input from stdin
const rl = readline.createInterface({
  input: process.stdin,
  output: null,
  terminal: false
})

const lines = []
rl.on('line', (line) => {
  lines.push(line)
})

rl.on('close', () => {
  try {
    const result = runElection(lines)
    if (mode === 'rounds') {
      for (const round of result.rounds) {
        process.stdout.write(formatRound(round))
      }
      if (result.eliminated.length > 0) {
        for (let i = 0; i < result.eliminated.length; i++) {
          process.stdout.write(`eliminated ${result.eliminated[i]}\n`)
          if (i < result.rounds.length - 1) {
            process.stdout.write(formatRound(result.rounds[i + 1]))
          }
        }
      }
    } else {
      process.stdout.write(`rounds ${result.rounds.length}\n`)
    }
    process.stdout.write(result.winner ? `winner ${result.winner}\n` : 'no winner\n')
  } catch (err) {
    process.stderr.write(err.message + '\n')
    process.exit(2)
  }
})

function formatRound(round) {
  const candidates = Object.entries(round.counts)
    .sort(([nameA, countA], [nameB, countB]) => {
      if (countA !== countB) return countB - countA
      return nameA < nameB ? -1 : 1
    })

  let output = `round ${round.number}: `
  output += candidates.map(([name, count]) => `${name}=${count}`).join(' ')
  output += ` exhausted=${round.exhausted}\n`
  return output
}

function runElection(lines) {
  // Parse input
  const parsed = parseInput(lines)
  const { candidates, ballots } = parsed

  if (candidates.length === 0) {
    throw new Error('error: no candidates')
  }

  // Initialize
  const continuing = new Set(candidates)
  const votes = Object.fromEntries(candidates.map(c => [c, 0]))
  const roundsData = []
  const eliminated = []
  const roundVotes = [] // Store votes for each candidate in each round for tiebreaking

  let winner = null

  // Run rounds
  for (let roundNum = 1; !winner; roundNum++) {
    // Count votes
    const roundCounts = Object.fromEntries(candidates.map(c => [c, 0]))
    let exhausted = 0

    for (const ballot of ballots) {
      let counted = false
      for (const candidate of ballot.candidates) {
        if (continuing.has(candidate)) {
          roundCounts[candidate] += ballot.count
          counted = true
          break
        }
      }
      if (!counted) {
        exhausted += ballot.count
      }
    }

    // Store round data
    roundsData.push({
      number: roundNum,
      counts: { ...roundCounts },
      exhausted
    })
    roundVotes.push({ ...roundCounts })

    // Calculate active total
    const activeTotal = Object.values(roundCounts).reduce((a, b) => a + b, 0)

    // Check for winner
    for (const candidate of continuing) {
      if (roundCounts[candidate] * 2 > activeTotal) {
        winner = candidate
        break
      }
    }

    if (winner) break

    // Check if no winner possible
    if (activeTotal === 0) break

    // Eliminate candidate with fewest votes
    const toEliminate = findCandidateToEliminate(continuing, roundCounts, roundVotes)
    continuing.delete(toEliminate)
    eliminated.push(toEliminate)
  }

  return {
    rounds: roundsData,
    eliminated,
    winner
  }
}

function findCandidateToEliminate(continuing, roundCounts, roundVotes) {
  const candidates = Array.from(continuing)

  // Start with candidates that have fewest votes this round
  let current = candidates.filter(c => {
    const minVotes = Math.min(...candidates.map(x => roundCounts[x]))
    return roundCounts[c] === minVotes
  })

  if (current.length === 1) return current[0]

  // Tiebreak across rounds
  for (let round = 0; round < roundVotes.length; round++) {
    const minVotes = Math.min(...current.map(c => roundVotes[round][c]))
    const newCurrent = current.filter(c => roundVotes[round][c] === minVotes)

    if (newCurrent.length === 1) return newCurrent[0]
    current = newCurrent
  }

  // If still tied, eliminate by last name code point
  current.sort((a, b) => b.localeCompare(a))
  return current[0]
}

function parseInput(lines) {
  const candidates = []
  const ballots = []
  let candidatesDeclared = false
  let lineNumber = 0

  for (const rawLine of lines) {
    lineNumber++

    // Split and process
    let line = rawLine.trim()

    // Drop trailing newline if present (already handled by readline)
    // Ignore empty lines or comments
    if (!line || line.startsWith('#')) {
      lineNumber--
      continue
    }

    // Split on whitespace
    const parts = line.split(/\s+/)
    if (parts.length === 0) {
      lineNumber--
      continue
    }

    const directive = parts[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        throw new Error(`error: line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      if (parts.length < 2) {
        throw new Error(`error: line ${lineNumber}: expected candidates <name>...`)
      }

      for (let i = 1; i < parts.length; i++) {
        const name = parts[i]

        // Validate candidate name
        if (!/^[A-Za-z0-9_-]+$/.test(name)) {
          throw new Error(`error: line ${lineNumber}: invalid candidate name ${name}`)
        }

        // Check for duplicates
        if (candidates.includes(name)) {
          throw new Error(`error: line ${lineNumber}: candidate ${name} is declared twice`)
        }

        candidates.push(name)
      }

      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw new Error(`error: line ${lineNumber}: candidates must be declared once, before any ballot`)
      }
      if (parts.length < 3) {
        throw new Error(`error: line ${lineNumber}: expected ballot <count> <candidate>...`)
      }

      // Parse count
      const countStr = parts[1]
      if (!/^\d+$/.test(countStr) || countStr.startsWith('0') && countStr.length > 1) {
        throw new Error(`error: line ${lineNumber}: count must be a positive integer`)
      }
      const count = parseInt(countStr, 10)
      if (count < 1) {
        throw new Error(`error: line ${lineNumber}: count must be a positive integer`)
      }

      // Parse ballot candidates
      const ballotCandidates = []
      const seen = new Set()

      for (let i = 2; i < parts.length; i++) {
        const name = parts[i]

        // Check if candidate is declared
        if (!candidates.includes(name)) {
          throw new Error(`error: line ${lineNumber}: unknown candidate ${name}`)
        }

        // Check for repeats
        if (seen.has(name)) {
          throw new Error(`error: line ${lineNumber}: candidate ${name} is repeated`)
        }

        seen.add(name)
        ballotCandidates.push(name)
      }

      ballots.push({
        count,
        candidates: ballotCandidates
      })
    } else {
      throw new Error(`error: line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  // Check if candidates were declared
  if (!candidatesDeclared) {
    throw new Error('error: no candidates')
  }

  return { candidates, ballots }
}
